import { useState } from 'react';
import { logScout } from '../api';

const DEFAULT_BATCH_SIZE = 45;

const TEMPLATES = [
  {
    name: 'Cold intro',
    subject: 'Quick question about {{store}}',
    body: `Hi,

I came across your store and loved what you're building.

I wanted to reach out because I think there's a real opportunity we could explore together.

Would you be open to a quick 10-minute chat this week?

Best,
{{name}}`,
  },
  {
    name: 'Collab offer',
    subject: 'Partnership opportunity for {{store}}',
    body: `Hey,

I run a brand in a complementary space and I think there's a great collab opportunity here.

I'll keep it short — would love to connect and explore if there's a fit.

Let me know if you're open to it.

{{name}}`,
  },
  {
    name: 'Custom',
    subject: '',
    body: '',
  },
];

function CopyBtn({ text, label }) {
  const [copied, setCopied] = useState(false);
  const copy = () => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 1800);
  };
  return (
    <button onClick={copy}
      style={{ background: copied ? 'var(--green-bg)' : 'var(--bg2)', color: copied ? 'var(--green)' : 'var(--text-muted)', border: `1px solid ${copied ? 'var(--green-border)' : 'var(--border-mid)'}`, padding: '7px 14px', borderRadius: 8, fontSize: 12, fontFamily: 'Syne', fontWeight: 600, cursor: 'pointer', display: 'inline-flex', alignItems: 'center', gap: 6, transition: 'all 0.2s' }}>
      {copied ? '✓ Copied' : `Copy ${label}`}
    </button>
  );
}

export default function ScoutMode({ emails, onBack }) {
  const [step, setStep]           = useState('setup'); // setup | batches | batch
  const [batchSize, setBatchSize] = useState(DEFAULT_BATCH_SIZE);
  const [template, setTemplate]   = useState(0);
  const [subject, setSubject]     = useState('');
  const [body, setBody]           = useState('');
  const [batches, setBatches]     = useState([]);
  const [activeBatch, setActiveBatch] = useState(null);
  const [sent, setSent]           = useState({});

  const handleTemplateSelect = (idx) => {
    setTemplate(idx);
    if (idx !== 2) {
      setSubject(TEMPLATES[idx].subject);
      setBody(TEMPLATES[idx].body);
    }
  };

  const handleReady = () => {
    if (!subject.trim() || !body.trim()) return;
    const chunks = [];
    for (let i = 0; i < emails.length; i += batchSize) {
      chunks.push(emails.slice(i, i + batchSize));
    }
    setBatches(chunks);
    setStep('batches');
  };

  const markSent = (idx) => {
    setSent(prev => ({ ...prev, [idx]: new Date().toLocaleTimeString() }));
    // Log to backend
    logScout(idx + 1, batches[idx].length, subject, batches.length);
    setActiveBatch(null);
  };

  const sentCount  = Object.keys(sent).length;
  const totalCount = batches.length;
  const pct        = totalCount > 0 ? Math.round((sentCount / totalCount) * 100) : 0;

  // ── Setup step ──────────────────────────────────────────────────────────────
  if (step === 'setup') {
    return (
      <div className="animate-in">
        <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 24 }}>
          <button onClick={onBack} style={{ background: 'none', border: 'none', color: 'var(--text-muted)', cursor: 'pointer', fontSize: 20, lineHeight: 1, padding: 0 }}>←</button>
          <div>
            <h2 style={{ fontFamily: 'Syne', fontSize: 19, fontWeight: 700, letterSpacing: '-0.02em', marginBottom: 2 }}>Scout mode</h2>
            <p style={{ color: 'var(--text-muted)', fontSize: 13 }}>{emails.length.toLocaleString()} emails ready to scout</p>
          </div>
        </div>

        {/* Batch size */}
        <div className="card" style={{ marginBottom: 16, padding: '20px 24px' }}>
          <div style={{ fontFamily: 'Syne', fontSize: 13, fontWeight: 600, marginBottom: 12 }}>Batch size</div>
          <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
            {[25, 45, 50, 100].map(n => (
              <button key={n} onClick={() => setBatchSize(n)}
                style={{ background: batchSize === n ? 'var(--accent)' : 'var(--bg3)', color: batchSize === n ? '#fff' : 'var(--text-muted)', border: `1px solid ${batchSize === n ? 'var(--accent)' : 'var(--border)'}`, padding: '8px 18px', borderRadius: 8, fontFamily: 'Syne', fontWeight: 600, fontSize: 13, cursor: 'pointer' }}>
                {n}
              </button>
            ))}
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <span style={{ fontSize: 12, color: 'var(--text-muted)' }}>Custom:</span>
              <input type="number" min={1} max={500} value={batchSize} onChange={e => setBatchSize(Number(e.target.value))}
                style={{ width: 80, padding: '8px 12px', fontSize: 13 }} />
            </div>
          </div>
          <div style={{ marginTop: 10, fontSize: 12, color: 'var(--text-dim)', fontFamily: 'DM Mono' }}>
            → {Math.ceil(emails.length / batchSize)} batches of ~{batchSize} emails each
          </div>
        </div>

        {/* Template picker */}
        <div className="card" style={{ marginBottom: 16, padding: '20px 24px' }}>
          <div style={{ fontFamily: 'Syne', fontSize: 13, fontWeight: 600, marginBottom: 12 }}>Email template</div>
          <div style={{ display: 'flex', gap: 8, marginBottom: 20, flexWrap: 'wrap' }}>
            {TEMPLATES.map((t, i) => (
              <button key={i} onClick={() => handleTemplateSelect(i)}
                style={{ background: template === i ? 'var(--accent)' : 'var(--bg3)', color: template === i ? '#fff' : 'var(--text-muted)', border: `1px solid ${template === i ? 'var(--accent)' : 'var(--border)'}`, padding: '8px 18px', borderRadius: 8, fontFamily: 'Syne', fontWeight: 600, fontSize: 12, cursor: 'pointer' }}>
                {t.name}
              </button>
            ))}
          </div>

          <div style={{ marginBottom: 14 }}>
            <label style={{ fontSize: 12, fontWeight: 500, color: 'var(--text-muted)', display: 'block', marginBottom: 6, fontFamily: 'Syne' }}>Subject line</label>
            <input placeholder="Your email subject..." value={subject} onChange={e => setSubject(e.target.value)} />
          </div>
          <div>
            <label style={{ fontSize: 12, fontWeight: 500, color: 'var(--text-muted)', display: 'block', marginBottom: 6, fontFamily: 'Syne' }}>Email body</label>
            <textarea placeholder="Write your message..." value={body} onChange={e => setBody(e.target.value)} style={{ minHeight: 180 }} />
          </div>
        </div>

        <button className="btn-primary" onClick={handleReady} disabled={!subject.trim() || !body.trim()}
          style={{ padding: '13px 28px', fontSize: 14 }}>
          Generate batches →
        </button>
      </div>
    );
  }

  // ── Batch detail ─────────────────────────────────────────────────────────────
  if (activeBatch !== null) {
    const batch     = batches[activeBatch];
    const bccString = batch.join(', ');
    const isSent    = !!sent[activeBatch];

    return (
      <div className="animate-in">
        <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 24 }}>
          <button onClick={() => setActiveBatch(null)} style={{ background: 'none', border: 'none', color: 'var(--text-muted)', cursor: 'pointer', fontSize: 20, lineHeight: 1, padding: 0 }}>←</button>
          <div>
            <h2 style={{ fontFamily: 'Syne', fontSize: 19, fontWeight: 700, letterSpacing: '-0.02em', marginBottom: 2 }}>
              Batch {activeBatch + 1} of {totalCount}
              {isSent && <span style={{ marginLeft: 10, fontSize: 12, color: 'var(--green)', fontFamily: 'DM Mono' }}>✓ Sent at {sent[activeBatch]}</span>}
            </h2>
            <p style={{ color: 'var(--text-muted)', fontSize: 13 }}>{batch.length} emails in this batch</p>
          </div>
        </div>

        {/* Steps */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12, marginBottom: 20 }}>

          {/* Step 1 — BCC */}
          <div className="card" style={{ padding: '18px 22px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
              <div>
                <div style={{ fontFamily: 'Syne', fontWeight: 600, fontSize: 13, marginBottom: 2 }}>Step 1 — Copy BCC emails</div>
                <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>Paste into the BCC field in Gmail (not CC — important)</div>
              </div>
              <CopyBtn text={bccString} label="BCC emails" />
            </div>
            <div style={{ background: 'var(--bg3)', borderRadius: 8, padding: '10px 14px', maxHeight: 80, overflowY: 'auto', fontFamily: 'DM Mono', fontSize: 11, color: 'var(--text-muted)', lineHeight: 1.7, wordBreak: 'break-all' }}>
              {bccString}
            </div>
          </div>

          {/* Step 2 — Subject */}
          <div className="card" style={{ padding: '18px 22px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div>
              <div style={{ fontFamily: 'Syne', fontWeight: 600, fontSize: 13, marginBottom: 2 }}>Step 2 — Copy subject</div>
              <div style={{ fontSize: 12, color: 'var(--text-muted)', fontFamily: 'DM Mono' }}>{subject}</div>
            </div>
            <CopyBtn text={subject} label="subject" />
          </div>

          {/* Step 3 — Body */}
          <div className="card" style={{ padding: '18px 22px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
              <div style={{ fontFamily: 'Syne', fontWeight: 600, fontSize: 13 }}>Step 3 — Copy message body</div>
              <CopyBtn text={body} label="body" />
            </div>
            <div style={{ background: 'var(--bg3)', borderRadius: 8, padding: '10px 14px', maxHeight: 120, overflowY: 'auto', fontFamily: 'DM Mono', fontSize: 11, color: 'var(--text-muted)', lineHeight: 1.8, whiteSpace: 'pre-wrap' }}>
              {body}
            </div>
          </div>

          {/* Step 4 — Open Gmail */}
          <div className="card" style={{ padding: '18px 22px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div>
              <div style={{ fontFamily: 'Syne', fontWeight: 600, fontSize: 13, marginBottom: 2 }}>Step 4 — Open Gmail compose</div>
              <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>Opens a new compose window — paste BCC, subject, body then send</div>
            </div>
            <a href="https://mail.google.com/mail/?view=cm&fs=1" target="_blank" rel="noreferrer">
              <button style={{ background: 'var(--accent)', color: '#fff', border: 'none', padding: '9px 18px', borderRadius: 8, fontSize: 12, fontFamily: 'Syne', fontWeight: 600, cursor: 'pointer' }}>
                Open Gmail ↗
              </button>
            </a>
          </div>
        </div>

        {/* Mark sent */}
        {!isSent ? (
          <button className="btn-primary" onClick={() => markSent(activeBatch)}
            style={{ padding: '13px 28px', fontSize: 14, background: 'var(--green)', borderColor: 'var(--green)' }}>
            ✓ Mark batch {activeBatch + 1} as sent
          </button>
        ) : (
          <div style={{ display: 'flex', gap: 10 }}>
            {activeBatch < totalCount - 1 && (
              <button className="btn-primary" onClick={() => setActiveBatch(activeBatch + 1)} style={{ padding: '13px 28px', fontSize: 14 }}>
                Next batch →
              </button>
            )}
          </div>
        )}
      </div>
    );
  }

  // ── Batches overview ─────────────────────────────────────────────────────────
  return (
    <div className="animate-in">
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 24 }}>
        <button onClick={() => setStep('setup')} style={{ background: 'none', border: 'none', color: 'var(--text-muted)', cursor: 'pointer', fontSize: 20, lineHeight: 1, padding: 0 }}>←</button>
        <div>
          <h2 style={{ fontFamily: 'Syne', fontSize: 19, fontWeight: 700, letterSpacing: '-0.02em', marginBottom: 2 }}>Scout progress</h2>
          <p style={{ color: 'var(--text-muted)', fontSize: 13 }}>{sentCount} of {totalCount} batches sent · {emails.length.toLocaleString()} total emails</p>
        </div>
      </div>

      {/* Progress bar */}
      <div className="card" style={{ padding: '20px 24px', marginBottom: 20 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: 12 }}>
          <div style={{ fontSize: 13, color: 'var(--text-muted)', fontFamily: 'DM Mono' }}>
            {sentCount === totalCount ? '✓ All batches sent!' : `${totalCount - sentCount} batches remaining`}
          </div>
          <div style={{ fontFamily: 'Syne', fontSize: 28, fontWeight: 700, letterSpacing: '-0.03em', color: sentCount === totalCount ? 'var(--green)' : 'var(--text)' }}>
            {pct}%
          </div>
        </div>
        <div style={{ height: 8, background: 'var(--bg3)', borderRadius: 99, overflow: 'hidden' }}>
          <div style={{ height: '100%', width: `${pct}%`, background: sentCount === totalCount ? 'var(--green)' : 'var(--accent)', borderRadius: 99, transition: 'width 0.5s ease' }} />
        </div>
        <div style={{ marginTop: 10, display: 'flex', gap: 20, fontSize: 12, color: 'var(--text-dim)', fontFamily: 'DM Mono' }}>
          <span>✓ {sentCount} sent</span>
          <span>· {totalCount - sentCount} pending</span>
          <span>· {(sentCount * batchSize).toLocaleString()} emails reached</span>
        </div>
      </div>

      {/* Batch list */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        {batches.map((batch, i) => {
          const isSent = !!sent[i];
          return (
            <div key={i}
              style={{ background: 'var(--bg2)', border: `1px solid ${isSent ? 'var(--green-border)' : 'var(--border)'}`, borderRadius: 'var(--radius-lg)', padding: '14px 20px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', boxShadow: 'var(--shadow-sm)', transition: 'all 0.15s' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 14 }}>
                <div style={{ width: 34, height: 34, background: isSent ? 'var(--green-bg)' : 'var(--bg3)', border: `1px solid ${isSent ? 'var(--green-border)' : 'var(--border)'}`, borderRadius: 8, display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: 'Syne', fontWeight: 700, fontSize: 13, color: isSent ? 'var(--green)' : 'var(--text-muted)' }}>
                  {isSent ? '✓' : i + 1}
                </div>
                <div>
                  <div style={{ fontFamily: 'Syne', fontWeight: 600, fontSize: 13 }}>Batch {i + 1}</div>
                  <div style={{ fontSize: 12, color: 'var(--text-muted)', fontFamily: 'DM Mono' }}>
                    {batch.length} emails
                    {isSent && <span style={{ marginLeft: 8, color: 'var(--green)' }}>· sent at {sent[i]}</span>}
                  </div>
                </div>
              </div>
              <button onClick={() => setActiveBatch(i)}
                style={{ background: isSent ? 'var(--green-bg)' : 'var(--accent)', color: isSent ? 'var(--green)' : '#fff', border: `1px solid ${isSent ? 'var(--green-border)' : 'transparent'}`, padding: '8px 18px', borderRadius: 8, fontFamily: 'Syne', fontWeight: 600, fontSize: 12, cursor: 'pointer' }}>
                {isSent ? 'View again' : 'Send this batch →'}
              </button>
            </div>
          );
        })}
      </div>

      <button className="btn-ghost" onClick={onBack} style={{ marginTop: 20 }}>← Back to results</button>
    </div>
  );
}
